import { writeTree, type FileTree } from '../write-tree.js';

/** A small Python service: pyproject metadata, a Poetry lockfile, pytest-style tests, no CI. */
export function pythonServiceTree(): FileTree {
  return {
    'pyproject.toml': [
      '[project]',
      'name = "inventory-service"',
      'description = "Tracks stock levels for the warehouse."',
      'requires-python = ">=3.11"',
      '',
      '[tool.pytest.ini_options]',
      'testpaths = ["tests"]',
      '',
    ].join('\n'),
    'poetry.lock': '# This file is automatically @generated by Poetry.\n',
    '.gitignore': '__pycache__/\n.venv/\n',
    LICENSE: 'MIT License\n',
    'README.md': '# inventory-service\n\nTracks stock levels.\n',
    'inventory/__init__.py': '',
    'inventory/stock.py': [
      'def reserve(stock: dict[str, int], sku: str, quantity: int) -> dict[str, int]:',
      '    if stock.get(sku, 0) < quantity:',
      '        raise ValueError("insufficient stock")',
      '    return {**stock, sku: stock[sku] - quantity}',
      '',
    ].join('\n'),
    'tests/test_stock.py': [
      'from inventory.stock import reserve',
      '',
      '',
      'def test_reserve_decrements_stock():',
      '    assert reserve({"a": 2}, "a", 1) == {"a": 1}',
      '',
    ].join('\n'),
  };
}

export async function buildPythonServiceFixture(root: string): Promise<void> {
  await writeTree(root, pythonServiceTree());
}
